import{_ as r,o,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Using rbd Migration Tooling in Our Ceph Operations - Daniel Radjenovic, DigitalOcean","description":"","frontmatter":{"title":"Using rbd Migration Tooling in Our Ceph Operations - Daniel Radjenovic, DigitalOcean","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","RBD迁移","分布式存储","数字海洋","自动化工具"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Using_rbd_Migration_Tooling_in_Our_Ceph_Operations_-_Daniel_Radjenovic_DigitalOcean.md","filePath":"posts/2025/Using_rbd_Migration_Tooling_in_Our_Ceph_Operations_-_Daniel_Radjenovic_DigitalOcean.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Using_rbd_Migration_Tooling_in_Our_Ceph_Operations_-_Daniel_Radjenovic_DigitalOcean.md"};function i(l,a,s,g,_,h){return o(),e("div",null,[...a[0]||(a[0]=[t('<h3 id="ceph-rbd迁移工具链实践分享" tabindex="-1"><strong>Ceph RBD迁移工具链实践分享</strong> <a class="header-anchor" href="#ceph-rbd迁移工具链实践分享" aria-label="Permalink to &quot;**Ceph RBD迁移工具链实践分享**&quot;">​</a></h3><h4 id="会议主题" tabindex="-1"><strong>会议主题</strong> <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;**会议主题**&quot;">​</a></h4><p>DigitalOcean存储系统团队（Daniel、Matt、Tyler、Shawn）分享了他们在Ceph集群间进行RBD镜像迁移的实用工具链，包括Gantry、Elvos和Seale的设计背景、功能以及未来优化方向。</p><h4 id="_1-背景与原因" tabindex="-1"><strong>1. 背景与原因</strong> <a class="header-anchor" href="#_1-背景与原因" aria-label="Permalink to &quot;**1. 背景与原因**&quot;">​</a></h4><p>团队选择部署多个小型Ceph集群而非单一大型集群，原因如下：</p><ol><li><strong>故障域控制</strong>：维护或升级时，仅影响部分客户，快速升级。</li><li><strong>成本与扩展性</strong>：新区域成本低，填充后直接新增集群而非扩容。</li><li><strong>文件描述符限制</strong>：多集群减少hypervisor的文件描述符压力。</li><li><strong>风险缓解</strong>：新集群可从干净状态启动，逐步淘汰旧集群。</li></ol><h4 id="_2-迁移工具介绍" tabindex="-1"><strong>2. 迁移工具介绍</strong> <a class="header-anchor" href="#_2-迁移工具介绍" aria-label="Permalink to &quot;**2. 迁移工具介绍**&quot;">​</a></h4><h4 id="_1-gantry" tabindex="-1">(1) Gantry <a class="header-anchor" href="#_1-gantry" aria-label="Permalink to &quot;(1) Gantry&quot;">​</a></h4><ul><li><strong>功能</strong>：基于RBD mirroring，实现非在线RBD镜像迁移。</li><li><strong>流程</strong>：设置集群间replication peers，同步数据至目标集群，Promote/Demote操作后禁用mirroring。</li><li><strong>优点</strong>：快速、支持snapshots同步。</li><li><strong>局限</strong>：迁移需关闭VM，影响客户体验。</li></ul><h4 id="_2-elvos" tabindex="-1">(2) Elvos <a class="header-anchor" href="#_2-elvos" aria-label="Permalink to &quot;(2) Elvos&quot;">​</a></h4><ul><li><strong>功能</strong>：支持在线迁移（VM无需停机）。</li><li><strong>技术</strong>：基于QEMU block jobs，实时同步数据至目标集群。</li><li><strong>流程</strong>：创建目标集群的RBD镜像，发起QEMU block job，检测convergence后切换VM至目标镜像。</li><li><strong>挑战</strong>：引入额外latency，需进一步优化。</li></ul><h4 id="_3-seale" tabindex="-1">(3) Seale <a class="header-anchor" href="#_3-seale" aria-label="Permalink to &quot;(3) Seale&quot;">​</a></h4><ul><li><strong>功能</strong>：自动化迁移决策工具。</li><li><strong>场景</strong>：检测集群fill level，提议批量迁移，一键清空旧集群。</li><li><strong>优势</strong>：替代手动管理TXT文件，通过Slack交互式审批流程。</li></ul><h4 id="_3-工具链对比" tabindex="-1"><strong>3. 工具链对比</strong> <a class="header-anchor" href="#_3-工具链对比" aria-label="Permalink to &quot;**3. 工具链对比**&quot;">​</a></h4><p>| 工具 | 适用场景 | 核心技术 | 关键优势 |<br> |||-||<br> | Gantry | 非在线 <strong>RBD</strong> 迁移 | RBD mirroring | 快速、支持快照 |<br> | Elvos | 在线 <strong>VM-attached</strong> 迁移 | QEMU block jobs | 无需停机 |<br> | Seale | 自动化迁移决策 | 集群监控+调度 | 简化批量操作 |</p><h4 id="_4-后续行动计划" tabindex="-1"><strong>4. 后续行动计划</strong> <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;**4. 后续行动计划**&quot;">​</a></h4><ol><li><strong>优化Elvos</strong>：降低迁移对客户latency的影响。</li><li><strong>分层存储支持</strong>：开发工具支持客户数据在不同storage tier间迁移。</li><li><strong>持续自动化</strong>：增强Seale的智能调度能力。</li></ol><h3 id="总结" tabindex="-1"><strong>总结</strong> <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**&quot;">​</a></h3><p>DigitalOcean团队通过Gantry、Elvos和Seale的迭代，实现了从手动到自动化、离线和在线迁移的全覆盖，显著提升了Ceph集群管理的灵活性与效率。未来将聚焦性能优化和分层存储支持，进一步强化分布式存储的运维能力。</p>',19)])])}const p=r(n,[["render",i]]);export{c as __pageData,p as default};
